// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        // fund the contract via its payable fallback from a random funder
        address funder = address(uint160(uint256(keccak256(abi.encode(actor, amount)))) | 1);
        vm.assume(funder != address(c) && funder != address(this));
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        if (address(c).balance == 0) return; // nothing to withdraw; rule vacuous

        // an arbitrary (possibly non-owner) actor attempts to drain the contract
        bool ok;
        vm.prank(actor);
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // RULE: a non-owner's withdrawAll must always revert (balance untouched);
        // the owner's call succeeds and drains to zero.
        assertTrue(
            (ok && address(c).balance == 0) || (!ok && address(c).balance == amount),
            "only owner may drain"
        );
    }
}

