pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        amount = bound(amount, 1 ether, 1000 ether);

        // fund the contract with a fuzzed amount
        vm.deal(address(c), amount);

        // an arbitrary (fuzzed) actor attempts to drain the contract
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // GENERAL RULE: the drain attempt succeeds if and only if the caller is
        // the owner; for a non-owner the call must revert and the balance stays.
        // The mutant lets any non-owner succeed, so ok becomes true for actor != owner.
        assertTrue(ok == (actor == c.owner()), "withdrawAll must succeed only for the owner");
    }
}

