pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address funder, address actor, uint256 amount) public {
        vm.assume(funder != address(0) && funder != address(c));
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(actor != c.owner());
        amount = bound(amount, 1, type(uint256).max / 2);

        // fund the contract via its payable fallback
        vm.deal(funder, amount);
        vm.prank(funder);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(ok);

        // a non-owner attempts to drain the contract
        vm.prank(actor);
        bool drained;
        try c.withdrawAll() {
            drained = true;
        } catch {
            drained = false;
        }

        // rule: a non-owner withdrawAll must revert and the balance must be untouched
        assertTrue(!drained && address(c).balance == amount && c.depositsCount() == 1);
    }
}

