import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // keep the domain admissible: depositor must not be the test/owner contract or c itself
        vm.assume(actor != address(this) && actor != address(c) && actor != address(0));

        // arbitrary external party deposits via the fallback, bumping depositsCount
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool dep, ) = address(c).call{value: amount}("");
        require(dep, "deposit failed");

        uint256 before = c.depositsCount();

        // owner drives the entry under test
        vm.prank(address(this));
        c.withdrawAll();

        // RULE: withdrawAll never changes depositsCount; the mutant increments it an extra time
        assertTrue(c.depositsCount() == before);
    }
}

