pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= address(this).balance + amount); // no-op guard for overflow-free math below
        vm.deal(address(this), amount);
        if (amount > 0) {
            (bool s, ) = address(c).call{value: amount}("");
            assertTrue(s);
        }
        vm.deal(actor, 1);
        uint256 before = address(c).balance;
        vm.prank(actor);
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        // owner-only withdraw: for non-owner actor it must revert; for owner it must move `amount` out.
        if (actor == c.owner()) {
            assertTrue(ok && address(c).balance == before - amount);
        } else {
            assertTrue(!ok && address(c).balance == before);
        }
    }
}

