contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint128 seedAmount, uint128 withdrawAmount) public {
        vm.assume(withdrawAmount < seedAmount);
        address owner = c.owner();

        // fund the contract via fallback so it holds more than the withdrawn amount
        address funder = address(0xBEEF);
        vm.deal(funder, seedAmount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: seedAmount}("");
        assertTrue(sent);

        uint256 before = address(c).balance;

        vm.prank(owner);
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.withdraw.selector, uint256(withdrawAmount)));
        assertTrue(ok);

        assertTrue(address(c).balance == before - uint256(withdrawAmount));
    }
}

